/// One of: GetterClause, SetterClause, RefClause, MutatingRefClause.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum AccessorClause {
    GetterClause(GetterClause),
    SetterClause(SetterClause),
    RefClause(RefClause),
    MutatingRefClause(MutatingRefClause),
}

impl AstNode for AccessorClause {
    fn can_cast(kind: SyntaxKind) -> bool {
        matches!(
            kind,
            SyntaxKind::GetterClause
                | SyntaxKind::SetterClause
                | SyntaxKind::RefClause
                | SyntaxKind::MutatingRefClause
        )
    }
    fn cast(syntax: SyntaxNode) -> Option<Self> {
        Some(match syntax.kind() {
            SyntaxKind::GetterClause => AccessorClause::GetterClause(GetterClause { syntax }),
            SyntaxKind::SetterClause => AccessorClause::SetterClause(SetterClause { syntax }),
            SyntaxKind::RefClause => AccessorClause::RefClause(RefClause { syntax }),
            SyntaxKind::MutatingRefClause => {
                AccessorClause::MutatingRefClause(MutatingRefClause { syntax })
            },
            _ => return None,
        })
    }
    fn syntax(&self) -> &SyntaxNode {
        match self {
            AccessorClause::GetterClause(it) => &it.syntax,
            AccessorClause::SetterClause(it) => &it.syntax,
            AccessorClause::RefClause(it) => &it.syntax,
            AccessorClause::MutatingRefClause(it) => &it.syntax,
        }
    }
}

impl From<GetterClause> for AccessorClause {
    fn from(node: GetterClause) -> AccessorClause {
        AccessorClause::GetterClause(node)
    }
}

impl From<SetterClause> for AccessorClause {
    fn from(node: SetterClause) -> AccessorClause {
        AccessorClause::SetterClause(node)
    }
}

impl From<RefClause> for AccessorClause {
    fn from(node: RefClause) -> AccessorClause {
        AccessorClause::RefClause(node)
    }
}

impl From<MutatingRefClause> for AccessorClause {
    fn from(node: MutatingRefClause) -> AccessorClause {
        AccessorClause::MutatingRefClause(node)
    }
}

