/// One of: TypeBound, TypeEquality.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum WhereConstraint {
    TypeBound(TypeBound),
    TypeEquality(TypeEquality),
}

impl AstNode for WhereConstraint {
    fn can_cast(kind: SyntaxKind) -> bool {
        matches!(kind, SyntaxKind::TypeBound | SyntaxKind::TypeEquality)
    }
    fn cast(syntax: SyntaxNode) -> Option<Self> {
        Some(match syntax.kind() {
            SyntaxKind::TypeBound => WhereConstraint::TypeBound(TypeBound { syntax }),
            SyntaxKind::TypeEquality => WhereConstraint::TypeEquality(TypeEquality { syntax }),
            _ => return None,
        })
    }
    fn syntax(&self) -> &SyntaxNode {
        match self {
            WhereConstraint::TypeBound(it) => &it.syntax,
            WhereConstraint::TypeEquality(it) => &it.syntax,
        }
    }
}

impl From<TypeBound> for WhereConstraint {
    fn from(node: TypeBound) -> WhereConstraint {
        WhereConstraint::TypeBound(node)
    }
}

impl From<TypeEquality> for WhereConstraint {
    fn from(node: TypeEquality) -> WhereConstraint {
        WhereConstraint::TypeEquality(node)
    }
}
